directive duration 36000.0 points 1000

(* remove the following two lines and set the compilation and simulation modes manually for version v2014-0219 or earlier *)
directive compilation infinite
directive simulation deterministic

directive plot <_ _ _ Fluor10> (* output: Fluor[10] *)

def N = 10 (* 0.1x standard concentration *)
def OFF = 1*N (* logic OFF value = 0.1 *)
def ON = 9*N (* logic ON value = 0.9 *)
def unbind = 0.1126 (* normal toehold dissociation rate constant /s *)
def fastunbind = 0.95 (* fast toehold dissociation rate constant /s *)
def fast = 0.012 (* fast toehold binding rate constant /nM/s *)
def normal = 0.0003 (* normal toehold binding rate constant /nM/s *)
def slow = 0.000015 (* slow toehold binding rate constant /nM/s *)
new T@slow,fastunbind

(* a seesaw signal *)
def signal(N,iL,i,iR,jL,j,jR) = ( N * <iL^ i iR^ T^ jL^ j jR^> )

(* a seesaw gate with signal bound by the left side *)
def gateL(N,iL,i,iR,jL,j,jR) = ( N * {T^*}[iL^ i iR^ T^]<jL^ j jR^> )

(* a seesaw gate with signal bound by the right side *)
def gateR(N,iL,i,iR,jL,j,jR) = ( N * <iL^ i iR^>[T^ jL^ j jR^]{T^*} )

(* a seesaw threshold with signal coming in from the left side *)
def thresholdL(N,iR,jL,j,jR) = ( N * {iR^* T^*}[jL^ j jR^] )

(* a seesaw threshold with signal coming in from the right side *)
def thresholdR(N,iL,i,iR,jL) = ( N * [iL^ i iR^]{T^* jL^*} )

(* a seesaw reporter *)
def reporter(N,iL,i,iR,Fluor) = ( N * {T^*}[iL^ i iR^]<Fluor> )

(* 2-input 1-output seesaw OR gate *)
def seesawOR2I1O(i1L,i1,i1R,i2L,i2,i2R,k1L,k1,k1R) =
( gateL(20*N,i1L,i1,i1R,i2L,i2,i2R)
| thresholdL(6*N,i1R,i2L,i2,i2R)
| gateL(10*N,i2L,i2,i2R,k1L,k1,k1R)
| signal(20*N,i2L,i2,i2R,fL,f,fR))

(* 2-input 1-output seesaw AND gate *)
def seesawAND2I1O(i1L,i1,i1R,i2L,i2,i2R,k1L,k1,k1R) =
( gateL(20*N,i1L,i1,i1R,i2L,i2,i2R)
| thresholdL(12*N,i1R,i2L,i2,i2R)
| gateL(10*N,i2L,i2,i2R,k1L,k1,k1R)
| signal(20*N,i2L,i2,i2R,fL,f,fR))

(* 1-input 1-output seesaw OR gate *)
def seesawOR1I1O(i1L,i1,i1R,i2L,i2,i2R,k1L,k1,k1R) =
( gateL(10*N,i1L,i1,i1R,i2L,i2,i2R)
| thresholdL(6*N,i1R,i2L,i2,i2R)
| gateL(10*N,i2L,i2,i2R,k1L,k1,k1R)
| signal(20*N,i2L,i2,i2R,fL,f,fR))

(* reporter with signal restoration *)
def reporterREST(i1L,i1,i1R,i2L,i2,i2R,i3L,i3,i3R) =
( gateL(10*N,i1L,i1,i1R,i2L,i2,i2R)
| thresholdL(4*N,i1R,i2L,i2,i2R)
| gateL(10*N,i2L,i2,i2R,i3L,i3,i3R)
| signal(20*N,i2L,i2,i2R,fL,f,fR))

( signal(OFF,S1L,S1,S1R,S4L,S4,S4R) (* input w[1,4] *)
| signal(OFF,S2L,S2,S2R,S4L,S4,S4R) (* input w[2,4] *)
| signal(OFF,S3L,S3,S3R,S5L,S5,S5R) (* input w[3,5] *)
| seesawOR2I1O(S4L,S4,S4R,S7L,S7,S7R,S5L,S5,S5R)
| seesawAND2I1O(S5L,S5,S5R,S8L,S8,S8R,S6L,S6,S6R)
| seesawOR1I1O(S6L,S6,S6R,S9L,S9,S9R,S10L,S10,S10R)
| reporter(15*N,S10L,S10,S10R,Fluor10)
)
